"""Hosted lock-generation canaries; authored before the bootstrap producer."""

from __future__ import annotations

import hashlib
import json
from dataclasses import replace
from pathlib import Path

import pytest

from scripts import python_lock_bootstrap as producer

BASE = "a" * 40
HEAD = "b" * 40
ROOT = '[tool.poetry]\nname="assembly"\nrequires-poetry="2.4.1"\n'
LOCK = (
    "# This file is automatically @generated by Poetry 2.4.1 "
    "and should not be changed by hand.\n"
)
PACKAGE = "packages/dotmac-learning/"
SOURCE = PACKAGE + "src/dotmac_learning/"


def _file(path, content, before=None):
    return {
        "path": path,
        "before_sha256": before,
        "content": content,
        "sha256": hashlib.sha256(content.encode()).hexdigest(),
    }


def _document():
    return {
        "schema_version": 1,
        "base_sha": BASE,
        "package": "dotmac-learning",
        "files": [
            _file("pyproject.toml", ROOT, hashlib.sha256(ROOT.encode()).hexdigest()),
            _file(
                PACKAGE + "pyproject.toml", '[tool.poetry]\nname="dotmac-learning"\n'
            ),
        ],
        "package_sources": [
            _file(SOURCE + "__init__.py", '"""Reviewed source."""\n'),
            _file(SOURCE + "py.typed", ""),
            _file(PACKAGE + "README.md", "# Actual reviewed package\n"),
        ],
    }


def _proposal(document=None):
    return producer.parse_proposal(json.dumps(document or _document()).encode())


@pytest.mark.parametrize(
    "mutation",
    [
        "unknown",
        "missing",
        "version",
        "package",
        "base",
        "hash",
        "duplicate",
        "root_before",
        "new_before",
        "missing_source",
        "unknown_file_field",
    ],
)
def test_closed_proposal_rejects_each_independent_bad_input(mutation):
    document = _document()
    if mutation == "unknown":
        document["authorization"] = "approved"
    elif mutation == "missing":
        del document["base_sha"]
    elif mutation == "version":
        document["schema_version"] = True
    elif mutation == "package":
        document["package"] = "other"
    elif mutation == "base":
        document["base_sha"] = "main"
    elif mutation == "hash":
        document["package_sources"][0]["sha256"] = "0" * 64
    elif mutation == "duplicate":
        document["package_sources"].append(document["package_sources"][0])
    elif mutation == "root_before":
        document["files"][0]["before_sha256"] = None
    elif mutation == "new_before":
        document["files"][1]["before_sha256"] = "0" * 64
    elif mutation == "missing_source":
        document["package_sources"].pop()
    else:
        document["files"][0]["mode"] = "executable"
    with pytest.raises(producer.BootstrapError):
        _proposal(document)


@pytest.mark.parametrize(
    "path",
    [
        "/absolute/escape.py",
        "../escape.py",
        SOURCE + "../escape.py",
        SOURCE + ".git/config",
        SOURCE + "nested//file.py",
        SOURCE + "nested\\file.py",
        "scripts/escape.py",
        PACKAGE + "OTHER.md",
        "poetry.lock",
    ],
)
def test_proposal_paths_cannot_escape_the_two_metadata_and_closed_source_targets(path):
    document = _document()
    document["package_sources"].append(_file(path, "planted"))
    with pytest.raises(producer.BootstrapError):
        _proposal(document)
    assert (
        _proposal().package == "dotmac-learning"
    )  # same checker admits conforming input


def test_duplicate_json_keys_are_refused_instead_of_last_value_winning():
    with pytest.raises(producer.BootstrapError):
        producer.parse_proposal(b'{"schema_version":1,"schema_version":1}')


@pytest.fixture
def checkout(tmp_path, monkeypatch):
    repo = tmp_path / "checkout"
    repo.mkdir()
    (repo / "pyproject.toml").write_text(ROOT)
    (repo / "poetry.lock").write_text(LOCK)
    bootstrap = repo / ".github/bootstrap/poetry-requirements-py312.txt"
    bootstrap.parent.mkdir(parents=True)
    bootstrap.write_text("poetry==2.4.1 \\\n    --hash=sha256:fixture\n")
    paths = (
        "pyproject.toml",
        "poetry.lock",
        ".github/bootstrap/poetry-requirements-py312.txt",
    )

    def git(_repo, arguments):
        if arguments == ("rev-parse", "--verify", "HEAD"):
            return HEAD.encode()
        if arguments == ("rev-list", "--parents", "-n", "1", "HEAD"):
            return f"{HEAD} {BASE}".encode()
        if arguments in (
            ("show", BASE + ":pyproject.toml"),
            ("show", "HEAD:pyproject.toml"),
        ):
            return ROOT.encode()
        if arguments == ("ls-files", "-z", "--cached"):
            return b"\0".join(path.encode() for path in paths) + b"\0"
        if arguments[:2] == ("merge-base", "--is-ancestor") or arguments == (
            "diff",
            "--quiet",
            "HEAD",
            "--",
        ):
            return b""
        raise AssertionError(arguments)

    monkeypatch.setattr(producer, "_git", git)
    context = producer.HostedContext(HEAD, HEAD)
    monkeypatch.setattr(producer, "_require_hosted", lambda _repo: context)
    return repo, context


@pytest.mark.parametrize(
    "mutation",
    [
        "worktree",
        "committed",
        "base",
        "ancestry",
        "existing_new",
        "symlink",
        "pin",
        "different_pin",
        "bootstrap",
    ],
)
def test_checkout_binding_and_toolchain_fail_before_poetry_commands(
    checkout, monkeypatch, mutation
):
    repo, context = checkout
    proposal = _proposal()
    original_git = producer._git
    if mutation == "worktree":
        (repo / "pyproject.toml").write_text(ROOT + "# drift\n")
    elif mutation in {"committed", "base", "ancestry"}:

        def altered_git(root, arguments):
            if mutation == "committed" and arguments == ("show", "HEAD:pyproject.toml"):
                return (ROOT + "# committed drift\n").encode()
            if mutation == "base" and arguments == ("show", BASE + ":pyproject.toml"):
                return (ROOT + "# base drift\n").encode()
            if mutation == "ancestry" and arguments[:2] == (
                "merge-base",
                "--is-ancestor",
            ):
                raise producer.BootstrapError("base is not an ancestor")
            return original_git(root, arguments)

        monkeypatch.setattr(producer, "_git", altered_git)
    elif mutation == "existing_new":
        target = repo / (PACKAGE + "pyproject.toml")
        target.parent.mkdir(parents=True)
        target.write_text("existing")
    elif mutation == "symlink":
        target = repo / "packages"
        target.symlink_to(repo.parent, target_is_directory=True)
    elif mutation in {"pin", "different_pin"}:
        proposed_pin = ">=2.4" if mutation == "pin" else "2.3.1"
        content = ROOT.replace("2.4.1", proposed_pin)
        changed = replace(
            proposal.files[0],
            content=content,
            sha256=hashlib.sha256(content.encode()).hexdigest(),
        )
        proposal = replace(proposal, files=(changed,) + proposal.files[1:])
    else:
        (repo / ".github/bootstrap/poetry-requirements-py312.txt").write_text(
            "poetry==2.3.1\n"
        )
    if mutation == "pin":
        message = "^exact root Poetry pin required$"
    elif mutation == "different_pin":
        message = "^proposal cannot change the pinned Poetry toolchain$"
    else:
        message = None
    with pytest.raises(producer.BootstrapError, match=message):
        producer.validate_checkout(repo, proposal, context)


@pytest.mark.parametrize("version", ["Poetry is somewhere", "Poetry (version 2.3.1)"])
def test_active_poetry_malformed_or_wrong_pin_cannot_generate_lock(
    checkout, tmp_path, monkeypatch, version
):
    repo, _ = checkout
    proposal_path = repo / "proposal.json"
    proposal_path.write_text(json.dumps(_document()))
    commands = []

    def command(arguments, cwd, *, capture_stdout):
        commands.append(arguments)
        return version.encode()

    monkeypatch.setattr(producer, "_command", command)
    with pytest.raises(producer.BootstrapError):
        producer.produce_lock(repo, proposal_path, tmp_path / "artifact")
    assert commands == [("poetry", "--version")]


def test_producer_uses_ordinary_lock_in_copy_and_emits_hash_manifest(
    checkout, tmp_path, monkeypatch
):
    repo, _ = checkout
    proposal_path = repo / "proposal.json"
    raw = json.dumps(_document()).encode()
    proposal_path.write_bytes(raw)
    commands = []

    def command(arguments, cwd, *, capture_stdout):
        commands.append(arguments)
        if arguments == ("poetry", "--version"):
            return b"Poetry (version 2.4.1)"
        assert arguments == ("poetry", "lock", "--no-interaction")
        assert cwd != repo and capture_stdout is False
        assert (
            cwd / (SOURCE + "__init__.py")
        ).read_text() == '"""Reviewed source."""\n'
        assert (cwd / (PACKAGE + "README.md")).is_file()
        (cwd / "poetry.lock").write_text(LOCK + "# generated fixture\n")
        return b""

    monkeypatch.setattr(producer, "_command", command)
    output = tmp_path / "artifact"
    manifest = producer.produce_lock(repo, proposal_path, output)
    assert commands == [("poetry", "--version"), ("poetry", "lock", "--no-interaction")]
    assert (repo / "pyproject.toml").read_text() == ROOT
    assert not (repo / PACKAGE).exists()
    assert manifest.checkout_sha == HEAD and manifest.base_sha == BASE
    assert manifest.input_sha256 == hashlib.sha256(raw).hexdigest()
    assert (
        manifest.lock_sha256
        == hashlib.sha256((output / "poetry.lock").read_bytes()).hexdigest()
    )
    assert manifest.purpose == "generated_unqualified_lock"
    document = json.loads((output / "manifest.json").read_text())
    assert {item["path"] for item in document["proposed_files"]} == {
        item["path"] for item in _document()["files"] + _document()["package_sources"]
    }


def test_local_or_fork_context_is_refused_without_commands(tmp_path, monkeypatch):
    monkeypatch.delenv("GITHUB_ACTIONS", raising=False)
    with pytest.raises(producer.BootstrapError):
        producer._require_hosted(tmp_path)
    event_path = tmp_path / "event.json"
    event_path.write_text(
        json.dumps(
            {
                "pull_request": {
                    "head": {"sha": HEAD, "repo": {"full_name": "fork/repo"}},
                    "base": {"repo": {"full_name": "owner/repo"}},
                }
            }
        )
    )
    for name, value in {
        "GITHUB_ACTIONS": "true",
        "RUNNER_ENVIRONMENT": "github-hosted",
        "GITHUB_EVENT_NAME": "pull_request",
        "GITHUB_REPOSITORY": "owner/repo",
        "GITHUB_WORKSPACE": str(tmp_path),
        "GITHUB_EVENT_PATH": str(event_path),
        "GITHUB_SHA": HEAD,
    }.items():
        monkeypatch.setenv(name, value)
    with pytest.raises(producer.BootstrapError):
        producer._require_hosted(tmp_path)


@pytest.mark.parametrize(
    "metadata",
    [
        '[tool.poetry]\nrequires-poetry=">=2.4"\n',
        "[tool.poetry]\nrequires-poetry=true\n",
        "[tool.poetry]\n",
        "not TOML",
    ],
)
def test_malformed_poetry_pin_is_a_payload_free_refusal(metadata):
    with pytest.raises(producer.BootstrapError) as caught:
        producer._poetry_pin(metadata.encode())
    assert metadata not in str(caught.value)


def test_command_argv_is_not_interpreted_by_a_shell_and_failure_output_is_suppressed(
    tmp_path, monkeypatch
):
    from types import SimpleNamespace

    calls = []

    def run(arguments, **options):
        calls.append((arguments, options))
        return SimpleNamespace(returncode=1, stdout=b"sensitive-command-output")

    monkeypatch.setattr(producer.subprocess, "run", run)
    with pytest.raises(producer.BootstrapError) as caught:
        producer._command(
            ("poetry", "lock", "--no-interaction"), tmp_path, capture_stdout=False
        )
    assert "sensitive-command-output" not in str(caught.value)
    arguments, options = calls[0]
    assert arguments == ("poetry", "lock", "--no-interaction")
    assert options["shell"] is False
    assert options["stdin"] == producer.subprocess.DEVNULL
    assert options["stdout"] == producer.subprocess.DEVNULL
    assert options["stderr"] == producer.subprocess.DEVNULL
    assert options["env"]["GIT_NO_LAZY_FETCH"] == "1"
    assert options["env"]["GIT_TERMINAL_PROMPT"] == "0"


def test_proposal_file_paths_cannot_be_ancestors_of_other_proposed_files():
    document = _document()
    document["package_sources"].extend(
        [_file(SOURCE + "collision", "x"), _file(SOURCE + "collision/child.py", "y")]
    )
    with pytest.raises(producer.BootstrapError):
        _proposal(document)


def test_proposal_symlink_is_refused_before_commands(checkout, tmp_path):
    repo, _ = checkout
    real = repo / "real.json"
    real.write_text(json.dumps(_document()))
    link = repo / "proposal.json"
    link.symlink_to(real)
    with pytest.raises(producer.BootstrapError):
        producer.produce_lock(repo, link, tmp_path / "artifact")


def test_workflow_is_read_only_same_repo_hosted_and_separate_from_qualification():
    workflow = (
        Path(__file__).resolve().parents[2]
        / ".github/workflows/python-lock-bootstrap.yml"
    ).read_text()
    assert "pull_request_target" not in workflow
    assert "workflow_dispatch" not in workflow
    assert "contents: read" in workflow and "contents: write" not in workflow
    assert "head.repo.full_name == github.repository" in workflow
    assert "persist-credentials: false" in workflow
    assert "fetch-depth: 0" in workflow
    assert "retention-days: 7" in workflow
    assert "environment:" not in workflow and "secrets." not in workflow
    assert workflow.index("--validate") < workflow.index(
        "./.github/actions/setup-poetry"
    )
    assert "poetry install" not in workflow and "pytest" not in workflow


def test_generated_lock_cannot_claim_hashes_for_tool_modified_source(
    checkout, tmp_path, monkeypatch
):
    repo, _ = checkout
    proposal_path = repo / "proposal.json"
    proposal_path.write_text(json.dumps(_document()))

    def command(arguments, cwd, *, capture_stdout):
        if arguments == ("poetry", "--version"):
            return b"Poetry (version 2.4.1)"
        assert arguments == ("poetry", "lock", "--no-interaction")
        (cwd / "pyproject.toml").write_text(ROOT + "# tool mutation\n")
        return b""

    monkeypatch.setattr(producer, "_command", command)
    output = tmp_path / "artifact"
    with pytest.raises(producer.BootstrapError):
        producer.produce_lock(repo, proposal_path, output)
    assert not output.exists()
    assert (repo / "pyproject.toml").read_text() == ROOT
